while (root != nullptr) {
    if (root->is_leaf) {
        int left = 0, right = root->keys.size() - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (root->keys[mid] == key) {
                return true;
            } else if (root->keys[mid] < key) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return false;
    } else {
        int left = 0, right = root->keys.size() - 1;
        int pos = root->keys.size();
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (root->keys[mid] == key) {
                pos = mid;
                break;
            } else if (root->keys[mid] < key) {
                left = mid + 1;
            } else {
                pos = mid;
                right = mid - 1;
            }
        }
        root = root->children[pos];
    }
}
return false;

